#version __CONTEXT__

layout(location = 0) in vec2 in_position;
layout(location = 1) in vec2 in_texCoords;

out Data {
  vec2 texCoords;
} out_data;


void main() {
  out_data.texCoords = in_texCoords;
  gl_Position = vec4(in_position.xy, 0.0, 1.0);
}

